<?php

namespace app\common\library;

use think\Db;
use RuntimeException;

/** Phase 20.6 governance: detect -> preview -> confirm -> apply -> verify -> audit. */
class IpaGovernanceService
{
    public static function refreshIssues()
    {
        $bindings=Db::name('ipa_binding')->order('id asc')->select();$seen=[];$bundleMap=[];$now=time();
        foreach((array)$bindings as $b){$m=Db::name('ipa_metadata')->where('id',(int)$b['metadata_id'])->find();$c=Db::name('category')->where('id',(int)$b['category_id'])->find();if(!$m||!$c)continue;$bundle=trim((string)$m['bundle_id']);if($bundle!=='')$bundleMap[$bundle][]=[$b,$m,$c];
            $missing=Db::name('ipa_scan_task_item')->where('metadata_id',(int)$m['id'])->where('stage','missing')->order('id desc')->find();
            if($missing && (int)$missing['updatetime']>(int)$m['last_seen_at'])self::upsertIssue($seen,'ipa_missing',$c,$m,'remote_path',(string)$c['bt1a'],'','OpenList 最近一次扫描未发现已绑定 IPA','exact',$now);
            elseif(trim((string)$c['bt1a'])!==''&&trim((string)$m['public_url'])!==''&&trim((string)$c['bt1a'])!==trim((string)$m['public_url']))self::upsertIssue($seen,'path_mismatch',$c,$m,'bt1a',(string)$c['bt1a'],(string)$m['public_url'],'数据库安装地址与当前 OpenList 公开地址不一致','exact',$now);
            if(trim((string)$m['package_name'])!==''&&trim((string)$c['name'])!==trim((string)$m['package_name']))self::upsertIssue($seen,'metadata_mismatch',$c,$m,'name',(string)$c['name'],(string)$m['package_name'],'数据库应用名称与 IPA 元数据不一致','exact',$now);
            if(trim((string)$m['package_version'])!==''&&trim((string)$c['nickname'])!==trim((string)$m['package_version']))self::upsertIssue($seen,'version_mismatch',$c,$m,'nickname',(string)$c['nickname'],(string)$m['package_version'],'数据库版本与 IPA CFBundleShortVersionString 不一致','exact',$now);
            $dbSize=is_numeric($c['bt2a'])?(int)$c['bt2a']:0;$actual=(int)$m['file_size'];if($dbSize>0&&$actual>0){$delta=abs($dbSize-$actual);$tol=max(1024*1024,(int)round($actual*0.01));if($delta>$tol)self::upsertIssue($seen,'metadata_mismatch',$c,$m,'bt2a',(string)$c['bt2a'],(string)$actual,'数据库文件大小与 OpenList 实际大小差异超过容差','exact',$now);}
        }
        foreach($bundleMap as $bundle=>$rows){if(count($rows)<2)continue;foreach($rows as $triple){list($b,$m,$c)=$triple;self::upsertIssue($seen,'duplicate_bundle',$c,$m,'bundle_id',$bundle,$bundle,'同一 Bundle ID 当前绑定到 '.count($rows).' 条应用记录，需要人工确认版本/记录语义','exact',$now);}}
        $open=Db::name('ipa_governance_issue')->where('state','open');if($seen)$open->whereNotIn('issue_key',array_keys($seen));$open->update(['state'=>'resolved','last_verified_at'=>$now,'updatetime'=>$now]);
        return self::stats();
    }

    protected static function upsertIssue(array &$seen,$type,array $category,array $metadata,$field,$dbValue,$actualValue,$reason,$confidence,$now)
    {
        $key=hash('sha256',implode('|',[$type,(int)$category['id'],(int)$metadata['id'],$field]));$seen[$key]=1;$old=Db::name('ipa_governance_issue')->where('issue_key',$key)->find();$state=$old&&$old['state']==='ignored'&&(int)$old['ignore_until']>$now?'ignored':'open';$data=['category_id'=>(int)$category['id'],'metadata_id'=>(int)$metadata['id'],'issue_type'=>$type,'field_name'=>$field,'db_value'=>(string)$dbValue,'actual_value'=>(string)$actualValue,'reason'=>$reason,'confidence'=>$confidence,'state'=>$state,'last_verified_at'=>$now,'updatetime'=>$now];if($old)Db::name('ipa_governance_issue')->where('id',(int)$old['id'])->update($data);else{$data['issue_key']=$key;$data['ignore_until']=0;$data['plan_hash']='';$data['createtime']=$now;Db::name('ipa_governance_issue')->insert($data);}
    }

    public static function stats()
    {
        $rows=Db::name('ipa_governance_issue')->where('state','open')->field('issue_type,COUNT(*) AS c')->group('issue_type')->select();$out=['duplicate'=>0,'mismatch'=>0,'missing'=>0,'version'=>0,'total'=>0];foreach((array)$rows as $r){$c=(int)$r['c'];$out['total']+=$c;if($r['issue_type']==='duplicate_bundle')$out['duplicate']+=$c;elseif($r['issue_type']==='ipa_missing'||$r['issue_type']==='path_mismatch')$out['missing']+=$c;elseif($r['issue_type']==='version_mismatch')$out['version']+=$c;else$out['mismatch']+=$c;}return $out;
    }

    public static function listIssues($kind='',$limit=200)
    {
        $q=Db::name('ipa_governance_issue')->where('state','open');if($kind==='duplicate')$q->where('issue_type','duplicate_bundle');elseif($kind==='missing')$q->where('issue_type','in',['ipa_missing','path_mismatch']);elseif($kind==='version')$q->where('issue_type','version_mismatch');elseif($kind==='mismatch')$q->where('issue_type','metadata_mismatch');$rows=$q->order('id desc')->limit(max(1,min(500,(int)$limit)))->select();
        foreach((array)$rows as &$r){$c=Db::name('category')->where('id',(int)$r['category_id'])->field('name,nickname')->find();$m=Db::name('ipa_metadata')->where('id',(int)$r['metadata_id'])->field('file_name,remote_path,public_url,bundle_id,package_version,file_size')->find();$r['category_name']=$c?$c['name']:'';$r['category_version']=$c?$c['nickname']:'';$r['file_name']=$m?$m['file_name']:'';$r['remote_path']=$m?$m['remote_path']:'';$r['public_url']=$m?$m['public_url']:'';$r['bundle_id']=$m?$m['bundle_id']:'';$r['package_version']=$m?$m['package_version']:'';$r['file_size']=$m?(int)$m['file_size']:0;}unset($r);return $rows;
    }

    public static function preview($issueId,$mode)
    {
        $ctx=self::context($issueId);$i=$ctx['issue'];$c=$ctx['category'];$m=$ctx['metadata'];$mode=(string)$mode;$action='manual';$payload=[];
        if(in_array($i['issue_type'],['metadata_mismatch','version_mismatch'],true)&&$mode==='ipa_to_db'){$action='category_update';$payload=['field'=>$i['field_name'],'old'=>$i['db_value'],'new'=>$i['actual_value']];}
        elseif($i['issue_type']==='path_mismatch'&&$mode==='openlist_to_db'){$action='category_update';$payload=['field'=>'bt1a','old'=>$c['bt1a'],'new'=>$m['public_url']];}
        elseif($i['issue_type']==='path_mismatch'&&$mode==='db_to_openlist'){$source=IpaSourceConfig::first(false);if(!$source)throw new RuntimeException('IPA source config not found');$expected=self::pathFromPublicUrl($c['bt1a'],$source['public_url_template']);if($expected==='')throw new RuntimeException('无法从数据库下载地址映射 OpenList 目标路径');$from=IpaRemoteFile::normalizePath($m['remote_path']);$to=IpaRemoteFile::normalizePath($expected);if($from===$to)throw new RuntimeException('OpenList 路径已经与数据库一致');$action='openlist_path';$payload=['from'=>$from,'to'=>$to,'old_public_url'=>$m['public_url'],'new_public_url'=>IpaRemoteFile::publicUrl($source['public_url_template'],$to)];}
        else throw new RuntimeException('该异常/模式不允许自动修复');
        $plan=['issue_id'=>(int)$i['id'],'issue_key'=>$i['issue_key'],'issue_type'=>$i['issue_type'],'mode'=>$mode,'action'=>$action,'category_id'=>(int)$c['id'],'metadata_id'=>(int)$m['id'],'category_updatetime'=>(int)$c['updatetime'],'metadata_updatetime'=>(int)$m['updatetime'],'remote_path'=>$m['remote_path'],'md5'=>$m['md5'],'payload'=>$payload];$plan['plan_hash']=IpaFoundation::planHash($plan);Db::name('ipa_governance_issue')->where('id',(int)$i['id'])->update(['plan_hash'=>$plan['plan_hash'],'updatetime'=>time()]);return $plan;
    }

    public static function apply($issueId,$mode,$expectedPlanHash,$adminId=0)
    {
        $plan=self::preview($issueId,$mode);if(!hash_equals((string)$plan['plan_hash'],(string)$expectedPlanHash))throw new RuntimeException('治理计划已变化，请重新预览');$idem=IpaFoundation::idempotencyKey('governance_apply',['issue_id'=>(int)$issueId,'plan_hash'=>$plan['plan_hash']]);$oldLog=Db::name('ipa_operation_log')->where('idempotency_key',$idem)->find();if($oldLog&&$oldLog['state']==='success')return ['replayed'=>true,'operation_id'=>$oldLog['operation_id'],'verified'=>true];$operationId=substr(hash('sha256',$idem.'|'.uniqid('',true)),0,36);$now=time();Db::name('ipa_operation_log')->insert(['operation_id'=>$operationId,'idempotency_key'=>$idem,'operation_type'=>'governance_'.$plan['action'],'category_id'=>$plan['category_id'],'metadata_id'=>$plan['metadata_id'],'plan_hash'=>$plan['plan_hash'],'state'=>'running','before_json'=>json_encode($plan,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'after_json'=>'{}','result_json'=>'{}','error_message'=>'','admin_id'=>(int)$adminId,'started_at'=>$now,'finished_at'=>0,'createtime'=>$now,'updatetime'=>$now]);
        try{if($plan['action']==='category_update')self::applyCategoryUpdate($plan);elseif($plan['action']==='openlist_path')self::applyOpenListPath($plan);else throw new RuntimeException('unsupported governance action');$verified=self::verifyPlan($plan);if(!$verified)throw new RuntimeException('修复执行后验证失败');$finished=time();Db::name('ipa_operation_log')->where('operation_id',$operationId)->update(['state'=>'success','after_json'=>json_encode(['verified'=>true],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),'result_json'=>'{"verified":true}','finished_at'=>$finished,'updatetime'=>$finished]);Db::name('ipa_governance_issue')->where('id',(int)$issueId)->update(['state'=>'resolved','last_verified_at'=>$finished,'updatetime'=>$finished]);return ['operation_id'=>$operationId,'verified'=>true];}catch(\Exception $e){Db::name('ipa_operation_log')->where('operation_id',$operationId)->update(['state'=>'failed','error_message'=>mb_substr($e->getMessage(),0,2000,'UTF-8'),'finished_at'=>time(),'updatetime'=>time()]);throw $e;}
    }

    protected static function applyCategoryUpdate(array $plan){$field=$plan['payload']['field'];if(!in_array($field,['name','nickname','bt1a','bt2a'],true))throw new RuntimeException('治理字段不允许自动写库');Db::startTrans();try{$current=Db::name('category')->where('id',$plan['category_id'])->lock(true)->find();if(!$current||(int)$current['updatetime']!==(int)$plan['category_updatetime'])throw new RuntimeException('数据库记录已变化，请重新预览');Db::name('category')->where('id',$plan['category_id'])->update([$field=>$plan['payload']['new'],'updatetime'=>time()]);Db::commit();}catch(\Exception $e){Db::rollback();throw $e;}}
    protected static function applyOpenListPath(array $plan){$source=IpaSourceConfig::first(true);if(!$source)throw new RuntimeException('IPA source config not found');$client=IpaSourceConfig::clientFromRow($source);$from=$plan['payload']['from'];$to=$plan['payload']['to'];$fromDir=dirname($from);$toDir=dirname($to);$fromName=basename($from);$toName=basename($to);self::assertTargetFree($client,$toDir,$toName,$from);$current=$client->getFile($from);if((int)(isset($current['size'])?$current['size']:0)!==(int)Db::name('ipa_metadata')->where('id',$plan['metadata_id'])->value('file_size'))throw new RuntimeException('OpenList 源文件大小已变化，请重新扫描');if($fromName!==$toName){$client->rename($from,$toName);$from=IpaRemoteFile::joinPath($fromDir,$toName);$fromName=$toName;}if($fromDir!==$toDir)$client->move($fromDir,$toDir,[$fromName]);$client->getFile($to);$now=time();$newUrl=IpaRemoteFile::publicUrl($source['public_url_template'],$to);Db::startTrans();try{Db::name('ipa_metadata')->where('id',$plan['metadata_id'])->update(['remote_path'=>$to,'remote_path_hash'=>IpaRemoteFile::pathHash($to),'file_name'=>$toName,'public_url'=>$newUrl,'last_seen_at'=>$now,'updatetime'=>$now]);Db::name('ipa_binding')->where('metadata_id',$plan['metadata_id'])->update(['remote_path'=>$to,'remote_path_hash'=>IpaRemoteFile::pathHash($to),'last_seen_at'=>$now,'updatetime'=>$now]);Db::commit();}catch(\Exception $e){Db::rollback();throw $e;}}
    protected static function assertTargetFree(IpaOpenListClient $client,$dir,$name,$sourcePath){$listed=$client->listDirectory($dir,1,1000,true);foreach((array)$listed['content'] as $row){if(isset($row['name'])&&(string)$row['name']===(string)$name){$target=IpaRemoteFile::joinPath($dir,$name);if($target!==IpaRemoteFile::normalizePath($sourcePath))throw new RuntimeException('OpenList 目标文件已存在，禁止自动覆盖');}}}
    protected static function verifyPlan(array $plan){if($plan['action']==='category_update')return (string)Db::name('category')->where('id',$plan['category_id'])->value($plan['payload']['field'])===(string)$plan['payload']['new'];if($plan['action']==='openlist_path'){$m=Db::name('ipa_metadata')->where('id',$plan['metadata_id'])->find();return $m&&IpaRemoteFile::normalizePath($m['remote_path'])===IpaRemoteFile::normalizePath($plan['payload']['to']);}return false;}
    public static function ignore($issueId,$until,$adminId=0){$until=max(time()+60,(int)$until);Db::name('ipa_governance_issue')->where('id',(int)$issueId)->update(['state'=>'ignored','ignore_until'=>$until,'updatetime'=>time()]);return true;}
    public static function verifyIssue($issueId){self::refreshIssues();$row=Db::name('ipa_governance_issue')->where('id',(int)$issueId)->find();return $row?$row['state']==='resolved':true;}
    protected static function context($issueId){$i=Db::name('ipa_governance_issue')->where('id',(int)$issueId)->find();if(!$i)throw new RuntimeException('治理异常不存在');$c=Db::name('category')->where('id',(int)$i['category_id'])->find();$m=Db::name('ipa_metadata')->where('id',(int)$i['metadata_id'])->find();if(!$c||!$m)throw new RuntimeException('治理上下文记录已不存在');return ['issue'=>$i,'category'=>$c,'metadata'=>$m];}
    public static function pathFromPublicUrl($url,$template){$url=trim((string)$url);$template=trim((string)$template);if($url===''||$template==='')return '';$pos=strpos($template,'{path}');if($pos!==false){$prefix=substr($template,0,$pos);$suffix=substr($template,$pos+6);if(strpos($url,$prefix)!==0)return '';$middle=substr($url,strlen($prefix));if($suffix!==''&&substr($middle,-strlen($suffix))===$suffix)$middle=substr($middle,0,-strlen($suffix));return IpaRemoteFile::normalizePath(urldecode($middle));}$prefix=rtrim($template,'/').'/';if(strpos($url,$prefix)!==0)return '';return IpaRemoteFile::normalizePath(urldecode(substr($url,strlen($prefix))));}
}
